UPDATE /* LGUTLC00500.updateTransferData */
       LGCOM_TRANSFER_MNGT_N
   SET system_code        = #{systemCode}
     , module_code        = #{moduleCode}
     , file_path_name     = #{filePathName}
     , changed_detail     = #{changedDetail}
     , changed_version_no = #{changedVersionNo}
     , trans_req_date     = TO_DATE(#{transReqDate},'YYYY-MM-DD')
     , req_user_name      = #{reqUserName}
     , attribute001       = #{attribute001}
     , attribute002       = #{attribute002}
     , attribute003       = #{attribute003}
     , attribute004       = #{attribute004}
     , attribute005       = #{attribute005}
     , attribute006       = #{attribute006}
     , attribute007       = #{attribute007}
     , attribute008       = #{attribute008}
     , attribute009       = #{attribute009}
     , attribute010       = #{attribute010}
     , last_update_date   = SYSDATE
     , last_updated_by    = #{applicationUserId}
 WHERE transfer_seq_no    = #{transferSeqNo}

UPDATE /* LGUTLC00500.updateDevTransferResult */
       LGCOM_TRANSFER_MNGT_N
   SET dev_trans_user_id = #{applicationUserId}
     , dev_transfer_date = SYSDATE
     , last_update_date  = SYSDATE
     , last_updated_by   = #{applicationUserId}
 WHERE transfer_seq_no   = #{transferSeqNo}

